const run = async () => {
  // Check loaded fonts for DM Sans
  const fontStyles = ["Regular", "Medium", "SemiBold", "Bold", "Semi Bold"];
  const loaded = [];
  for (const style of fontStyles) {
    try {
      await figma.loadFontAsync({ family: "DM Sans", style });
      loaded.push(style);
    } catch (e) {
      // style not present under this exact name
    }
  }

  // Set current page to 03 · Workspace
  const pages = figma.root.children;
  let workspace = pages.find(p => p.name.includes("03 · Workspace"));
  if (!workspace) {
    workspace = figma.createPage();
    workspace.name = "03 · Workspace";
  }
  await figma.setCurrentPageAsync(workspace);

  throw new Error("Loaded fonts: " + loaded.join(", ") + " | Current page: " + workspace.name);
};
