async function buildWorkspace() {
  const workspace = figma.root.children.find(p => p.id === "4:2" || p.name.includes("03 · Workspace"));
  if (!workspace) {
    console.log("Error: Workspace page not found.");
    return "Error: Workspace page not found.";
  }

  // Switch page
  await figma.setCurrentPageAsync(workspace);

  // Clear existing content to make sure it's clean
  workspace.children.forEach(child => child.remove());

  // Load DM Sans fonts
  const fontStyles = ["Regular", "Medium", "Semi Bold", "Bold"];
  for (const style of fontStyles) {
    try {
      await figma.loadFontAsync({ family: "DM Sans", style });
    } catch (e) {
      console.log("Error loading font styling: " + style, e);
    }
  }

  // Colors
  const colors = {
    brand: { r: 0.388, g: 0.278, b: 0.922 }, // #6347EB
    brandLight: { r: 0.941, g: 0.933, b: 0.996 }, // #F0EEFE
    bg: { r: 0.973, g: 0.976, b: 0.988 }, // #F8F9FC
    surface: { r: 1, g: 1, b: 1 }, // #FFFFFF
    textDark: { r: 0.102, g: 0.102, b: 0.122 }, // #1A1A1F
    textMuted: { r: 0.502, g: 0.522, b: 0.569 }, // #808591
    textLight: { r: 0.659, g: 0.678, b: 0.722 }, // #A8ADB8
    border: { r: 0.914, g: 0.925, b: 0.941 }, // #E9ECEF
    autoTransport: { r: 0.235, g: 0.722, b: 0.627 }, // #3CB8A0 Teal
    billUtilities: { r: 0.98, g: 0.545, b: 0.235 }, // #FA8B3C Orange
    good: { r: 0.133, g: 0.773, b: 0.369 }, // #22C55E Green
    notBad: { r: 0.961, g: 0.62, b: 0.043 }, // #F59E0B Amber
    badgeBgGood: { r: 0.902, g: 0.965, b: 0.925 }, // #E6F6EC
    badgeBgNotBad: { r: 0.992, g: 0.957, b: 0.878 } // #FEF4E0
  };

  // Text helper
  function createText(text, fontSize, fontStyle, color) {
    const t = figma.createText();
    t.fontName = { family: "DM Sans", style: fontStyle };
    t.fontSize = fontSize;
    t.characters = text;
    t.fills = [{ type: "SOLID", color: color }];
    return t;
  }

  // Get assets
  const iconBackMaster = await figma.getNodeByIdAsync("2:2");
  const iconBillMaster = await figma.getNodeByIdAsync("2:3");
  const iconCarMaster = await figma.getNodeByIdAsync("2:4");
  const iconChevronDownMaster = await figma.getNodeByIdAsync("2:5");
  const iconChevronRightMaster = await figma.getNodeByIdAsync("2:6");
  const iconMoreMaster = await figma.getNodeByIdAsync("2:7");
  const iconOffersMaster = await figma.getNodeByIdAsync("2:8");
  const iconOverviewMaster = await figma.getNodeByIdAsync("2:9");
  const iconPlusMaster = await figma.getNodeByIdAsync("2:10");
  const iconSettingMaster = await figma.getNodeByIdAsync("2:11");
  const iconThisMonthMaster = await figma.getNodeByIdAsync("2:12");

  const logoAppleMaster = await figma.getNodeByIdAsync("2:13");
  const logoNetflixMaster = await figma.getNodeByIdAsync("2:14");
  const logoPatreonMaster = await figma.getNodeByIdAsync("2:15");
  const logoSpotifyMaster = await figma.getNodeByIdAsync("2:16");

  const statusBarMaster = await figma.getNodeByIdAsync("1:25");
  const homeIndicatorMaster = await figma.getNodeByIdAsync("1:35");

  // Tab bar helper
  function createTabBar(activeTab) {
    const nav = figma.createFrame();
    nav.name = "Tab Bar Component";
    nav.resize(375, 83);
    nav.fills = [{ type: "SOLID", color: colors.surface }];
    nav.layoutMode = "HORIZONTAL";
    nav.primaryAxisSizingMode = "FIXED";
    nav.counterAxisSizingMode = "FIXED";
    nav.primaryAxisAlignItems = "SPACE_BETWEEN";
    nav.counterAxisAlignItems = "CENTER";
    nav.paddingLeft = 16;
    nav.paddingRight = 16;
    nav.paddingTop = 10;
    nav.paddingBottom = 25;
    nav.effects = [{
      type: "DROP_SHADOW",
      color: { r: 0, g: 0, b: 0, a: 0.05 },
      offset: { x: 0, y: -4 },
      radius: 12,
      visible: true,
      blendMode: "NORMAL"
    }];

    const tabs = [
      { name: "Overview", icon: iconOverviewMaster },
      { name: "This Month", icon: iconThisMonthMaster },
      { name: "Offers", icon: iconOffersMaster },
      { name: "Setting", icon: iconSettingMaster }
    ];

    tabs.forEach(t => {
      const item = figma.createFrame();
      item.name = "Tab_" + t.name.replace(" ", "_");
      item.layoutMode = "VERTICAL";
      item.primaryAxisSizingMode = "AUTO";
      item.counterAxisSizingMode = "AUTO";
      item.primaryAxisAlignItems = "CENTER";
      item.counterAxisAlignItems = "CENTER";
      item.itemSpacing = 4;
      item.fills = [];

      const isCurrent = t.name === activeTab;
      const iconInst = t.icon.createInstance();
      iconInst.resize(24, 24);

      const label = createText(
        t.name,
        11,
        isCurrent ? "Semi Bold" : "Medium",
        isCurrent ? colors.brand : colors.textMuted
      );

      item.appendChild(iconInst);
      item.appendChild(label);
      nav.appendChild(item);
    });

    return nav;
  }

  // ==========================================
  // FRAME 1: 01_Expenses
  // ==========================================
  const f1 = figma.createFrame();
  f1.name = "01_Expenses";
  f1.resize(375, 960);
  f1.fills = [{ type: "SOLID", color: colors.bg }];
  workspace.appendChild(f1);

  // Status Bar & Home Indicator
  const sb1 = statusBarMaster.createInstance();
  sb1.x = 0; sb1.y = 0;
  f1.appendChild(sb1);

  const hi1 = homeIndicatorMaster.createInstance();
  hi1.x = 0; hi1.y = 960 - 34;
  f1.appendChild(hi1);

