  // Category card builder
  function createCategoryCard(catTitle, catTotal, iconMaster, catColor, items, cardName) {
    const card = figma.createFrame();
    card.name = cardName;
    card.resize(335, 80 + items.length * 64);
    card.cornerRadius = 20;
    card.fills = [{ type: "SOLID", color: colors.surface }];
    card.paddingLeft = 16; card.paddingRight = 16;
    card.paddingTop = 16; card.paddingBottom = 16;
    card.layoutMode = "VERTICAL";
    card.itemSpacing = 16;

    const cHead = figma.createFrame();
    cHead.name = "Category_Header";
    cHead.resize(303, 40);
    cHead.fills = [];
    cHead.layoutMode = "HORIZONTAL";
    cHead.primaryAxisAlignItems = "SPACE_BETWEEN";
    cHead.counterAxisAlignItems = "CENTER";

    const cLeft = figma.createFrame();
    cLeft.layoutMode = "HORIZONTAL"; cLeft.itemSpacing = 12; cLeft.counterAxisAlignItems = "CENTER"; cLeft.fills = [];
    const iconBox = figma.createFrame();
    iconBox.resize(40, 40); iconBox.cornerRadius = 12; iconBox.fills = [{ type: "SOLID", color: { r: catColor.r, g: catColor.g, b: catColor.b }, opacity: 0.15 }];
    iconBox.layoutMode = "HORIZONTAL"; iconBox.primaryAxisAlignItems = "CENTER"; iconBox.counterAxisAlignItems = "CENTER";
    const catIcon = iconMaster.createInstance();
    iconBox.appendChild(catIcon);
    cLeft.appendChild(iconBox);
    cLeft.appendChild(createText(catTitle, 16, "Bold", colors.textDark));

    const cRight = createText(catTotal, 16, "Bold", colors.textDark);
    cHead.appendChild(cLeft);
    cHead.appendChild(cRight);
    card.appendChild(cHead);

    items.forEach(it => {
      const itemRow = figma.createFrame();
      itemRow.name = "Item_" + it.title.replace(/\s+/g, "_");
      itemRow.resize(303, 48);
      itemRow.fills = [];
      itemRow.layoutMode = "VERTICAL";
      itemRow.itemSpacing = 6;

      const r1 = figma.createFrame();
      r1.resize(303, 20); r1.fills = []; r1.layoutMode = "HORIZONTAL"; r1.primaryAxisAlignItems = "SPACE_BETWEEN";
      r1.appendChild(createText(it.title, 14, "Medium", colors.textDark));

      const amtBox = figma.createFrame();
      amtBox.layoutMode = "HORIZONTAL"; amtBox.itemSpacing = 6; amtBox.fills = [];
      amtBox.appendChild(createText(it.amount, 14, "Semi Bold", colors.textDark));
      amtBox.appendChild(createText("· Left " + it.left, 13, "Regular", colors.textMuted));
      r1.appendChild(amtBox);

      const pBg = figma.createFrame();
      pBg.resize(303, 6); pBg.cornerRadius = 3; pBg.fills = [{ type: "SOLID", color: colors.border }];
      const pFill = figma.createFrame();
      pFill.resize(Math.round(303 * it.ratio), 6); pFill.cornerRadius = 3; pFill.fills = [{ type: "SOLID", color: catColor }];
      pBg.appendChild(pFill);

      itemRow.appendChild(r1);
      itemRow.appendChild(pBg);
      card.appendChild(itemRow);
    });

    return card;
  }

